SELECT * FROM cage_event_log
WHERE scan_batch_id = #{scanBatchId}

    AND event_type = #{eventType}

ORDER BY changed_at DESC
LIMIT #{limit} OFFSET #{offset}

SELECT * FROM cage_event_log WHERE 1=1
AND event_type = #{eventType}
AND (curr_campus_name = #{campusName} OR prev_campus_name = #{campusName})
AND changed_at >= #{startTime}
AND changed_at <= #{endTime}
AND ( cage_box_qr_code LIKE CONCAT('%', #{searchText}, '%') OR curr_position LIKE CONCAT('%', #{searchText}, '%') OR prev_position LIKE CONCAT('%', #{searchText}, '%') OR curr_room_name LIKE CONCAT('%', #{searchText}, '%') OR project_pi_name LIKE CONCAT('%', #{searchText}, '%') OR department_name LIKE CONCAT('%', #{searchText}, '%') OR detail_summary LIKE CONCAT('%', #{searchText}, '%') )
ORDER BY changed_at DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM cage_event_log WHERE 1=1
AND event_type = #{eventType}
AND (curr_campus_name = #{campusName} OR prev_campus_name = #{campusName})
AND changed_at >= #{startTime}
AND changed_at <= #{endTime}
AND ( cage_box_qr_code LIKE CONCAT('%', #{searchText}, '%') OR curr_position LIKE CONCAT('%', #{searchText}, '%') OR prev_position LIKE CONCAT('%', #{searchText}, '%') OR curr_room_name LIKE CONCAT('%', #{searchText}, '%') OR project_pi_name LIKE CONCAT('%', #{searchText}, '%') OR department_name LIKE CONCAT('%', #{searchText}, '%') OR detail_summary LIKE CONCAT('%', #{searchText}, '%') )

SELECT * FROM cage_event_log
WHERE cage_box_qr_code = #{cageBoxQrCode}
ORDER BY changed_at DESC
LIMIT #{limit}

SELECT COUNT(1) FROM cage_event_log
WHERE event_type = 'STATUS_REMOVED'
  AND detail_summary LIKE CONCAT('解除 «', #{statusCode}, '» %')
  AND curr_shelve_id = #{currShelveId}
  AND curr_position = #{currPosition}
  AND changed_at > #{sinceTime}
